"""Helpers for fine-tuning (fixed infrastructure - students do not edit this file).

Two callbacks implement the "do not forget COCO" strategy used in this lab:

1. `preserve_coco_head(model)`   - transfer learning of the classification head.
   Our dataset has 80 + N classes, so ultralytics builds a NEW head with 80 + N outputs and
   cannot reuse the pretrained classification layers (their shapes changed). This callback
   copies the pretrained head into the new one: the first 80 outputs keep exactly the COCO
   knowledge, only the N new outputs start from scratch.

2. `freeze_all_but_new_classes(model)` - train ONLY the N new class outputs.
   Backbone, neck, box regression and the 80 COCO class outputs are frozen (including their
   BatchNorm statistics), and gradients of the COCO rows are masked. Therefore the
   80 COCO scores are bit-for-bit those of the pretrained model, and nothing is forgotten.
   The price: new objects must be recognised from the frozen COCO features.
"""
from __future__ import annotations

import copy
from pathlib import Path
from typing import Callable

import yaml

from config import NUM_COCO_CLASSES, WEIGHTS_DIR


def get_device() -> str:
    """'0' (first GPU) when CUDA is available, otherwise 'cpu'."""
    try:
        import torch

        return "0" if torch.cuda.is_available() else "cpu"
    except Exception:
        return "cpu"


def resolve_weights(name_or_path: str) -> str:
    """Use weights/<name> when it exists, otherwise let ultralytics download <name>."""
    candidate = Path(name_or_path)
    if candidate.exists():
        return str(candidate)
    local = WEIGHTS_DIR / candidate.name
    return str(local) if local.exists() else str(name_or_path)


def dataset_num_classes(dataset_config: str) -> int:
    """Number of classes (COCO + custom) declared in a data.yaml file."""
    with open(dataset_config, "r", encoding="utf-8") as handle:
        names = yaml.safe_load(handle)["names"]
    return len(names)


def _unwrap(network):
    return getattr(network, "module", network)


# --------------------------------------------------------------------------- #
# 1. Copy the pretrained classification head into the bigger head
# --------------------------------------------------------------------------- #
def transfer_coco_head(src_head, dst_head) -> None:
    """Copy the pretrained classification branch (`cv3`) of `src_head` into `dst_head`.

    `dst_head` has more output classes (and, in ultralytics, slightly wider intermediate
    layers). Every tensor is copied into the overlapping slice. Connections from the
    *new* intermediate channels into the *old* ones are zeroed, so the first 80 class
    scores are exactly what the pretrained model produced. New class rows get small
    random weights (their bias already has ultralytics' prior initialisation).
    """
    import torch

    old_nc, new_nc = int(src_head.nc), int(dst_head.nc)
    if new_nc < old_nc:
        raise ValueError(f"New head has fewer classes ({new_nc}) than the pretrained one ({old_nc}).")

    src_state = src_head.cv3.state_dict()
    with torch.no_grad():
        for key, dst in dst_head.cv3.state_dict().items():
            src = src_state.get(key)
            if src is None or src.ndim != dst.ndim:
                continue
            src = src.to(device=dst.device, dtype=dst.dtype)
            if dst.shape == src.shape:
                dst.copy_(src)
                continue
            region = tuple(slice(0, min(a, b)) for a, b in zip(dst.shape, src.shape))
            dst[region] = src[region]
            if dst.ndim == 4 and dst.shape[1] > src.shape[1]:
                dst[: src.shape[0], src.shape[1]:] = 0  # old outputs ignore new channels

        for branch in dst_head.cv3:
            final = branch[-1]
            if isinstance(final, torch.nn.Conv2d) and final.out_channels > old_nc:
                final.weight[old_nc:].normal_(0.0, 0.01)


def preserve_coco_head(model) -> Callable:
    """Return an ultralytics callback that keeps the COCO knowledge of `model`.

    Register it with ``model.add_callback("on_pretrain_routine_end", callback)``. It runs
    after the trainer has built the 80 + N class model (and its EMA copy) and loaded all
    shape-compatible pretrained weights, and then fills in the classification head.
    """
    source_head = copy.deepcopy(model.model.model[-1]).cpu().eval()
    model.coco_head_preserved = True  # lets finetune.py detect that TODO 2 was done

    def _callback(trainer) -> None:
        network = _unwrap(trainer.model)
        transfer_coco_head(source_head, network.model[-1])
        ema = getattr(trainer, "ema", None)
        if ema is not None and getattr(ema, "ema", None) is not None:
            ema.ema.load_state_dict(network.state_dict())  # EMA copy starts identical

    return _callback


# --------------------------------------------------------------------------- #
# 2. Train only the new class outputs
# --------------------------------------------------------------------------- #
def freeze_all_but_new_classes(model, num_old: int = NUM_COCO_CLASSES) -> None:
    """Make fine-tuning update ONLY the output rows of the new classes (ids >= num_old).

    Registers ultralytics callbacks on `model`; call it before `model.train(...)`.
    """
    model.new_classes_only = True  # lets finetune.py detect that TODO 3 was done

    def _freeze(trainer) -> None:
        import torch

        network = _unwrap(trainer.model)
        head = network.model[-1]
        for parameter in network.parameters():
            parameter.requires_grad_(False)
        for branch in head.cv3:
            final = branch[-1]  # the 1x1 conv that outputs one score per class
            for parameter in (final.weight, final.bias):
                parameter.requires_grad_(True)
                mask = torch.zeros_like(parameter)
                mask[num_old:] = 1.0  # only the rows of the new classes may change
                parameter.register_hook(lambda grad, m=mask: grad * m)
        for group in trainer.optimizer.param_groups:
            group["weight_decay"] = 0.0  # weight decay would also shrink the frozen rows

    def _keep_batchnorm_frozen(trainer) -> None:
        # trainer.model.train() switches BatchNorm to training mode, which would update
        # their running statistics on the new data and silently change the COCO outputs.
        from torch.nn.modules.batchnorm import _BatchNorm

        for module in _unwrap(trainer.model).modules():
            if isinstance(module, _BatchNorm):
                module.eval()

    model.add_callback("on_pretrain_routine_end", _freeze)
    model.add_callback("on_train_batch_start", _keep_batchnorm_frozen)
